import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Extracts — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"extracts-01-overview-and-concepts.md","filePath":"extracts-01-overview-and-concepts.md"}'),i={name:"extracts-01-overview-and-concepts.md"};function n(s,e,d,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="extracts-—-overview-concepts" tabindex="-1">Extracts — Overview &amp; Concepts <a class="header-anchor" href="#extracts-—-overview-concepts" aria-label="Permalink to &quot;Extracts — Overview &amp; Concepts&quot;">​</a></h1><p><em>What they are, why they matter, and how they fit into Lodestone</em></p><hr><h2 id="what-is-an-extract" tabindex="-1">What Is an Extract? <a class="header-anchor" href="#what-is-an-extract" aria-label="Permalink to &quot;What Is an Extract?&quot;">​</a></h2><p>An Extract is a candidate product idea surfaced by AI through the analysis of a meeting transcript. Extracts are intentionally provisional — they are not Features, and they don&#39;t create work automatically. They exist in a holding state until you decide whether the idea is worth pursuing.</p><p>The name reflects what they are: ideas pulled directly from real conversations, unfiltered and uninterpreted, waiting for a human judgment call.</p><hr><h2 id="why-extracts-exist" tabindex="-1">Why Extracts Exist <a class="header-anchor" href="#why-extracts-exist" aria-label="Permalink to &quot;Why Extracts Exist&quot;">​</a></h2><p>Valuable product insights are routinely lost between the moment a customer says something important and the moment a PM writes it down. Notes taken during meetings are partial, filtered by what could be captured in real time, and colored by the note-taker&#39;s interpretation. Even with full transcripts, reviewing them to extract ideas is time-consuming work.</p><p>Extracts remove that final bottleneck. Instead of reviewing transcripts yourself, you upload them and let AI surface the ideas. You stay focused on the conversation while it&#39;s happening, then review the output afterward.</p><p>The result is a higher-fidelity signal — ideas captured directly from the source rather than passed through a layer of human interpretation.</p><hr><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><h3 id="extracts-are-not-features" tabindex="-1">Extracts Are Not Features <a class="header-anchor" href="#extracts-are-not-features" aria-label="Permalink to &quot;Extracts Are Not Features&quot;">​</a></h3><p>This is the most important thing to understand about Extracts. They are candidate ideas, not commitments. An Extract only becomes a Feature when you explicitly decide to add it to your backlog. Until then, it sits in a provisional state with no impact on your planning.</p><p>This separation is intentional — it keeps your backlog clean and ensures that only ideas you&#39;ve actively reviewed and chosen make it into your planning workflow.</p><h3 id="the-binary-decision" tabindex="-1">The Binary Decision <a class="header-anchor" href="#the-binary-decision" aria-label="Permalink to &quot;The Binary Decision&quot;">​</a></h3><p>Every Extract requires one of two actions:</p><ul><li><strong>Add to Backlog</strong> — promotes the Extract to a Feature, carrying over the Feature Name and Description</li><li><strong>Dismiss</strong> — permanently deletes the Extract</li></ul><p>There is no intermediate state, no &quot;maybe later&quot; pile, and no way to recover a dismissed Extract. The module is designed to be decisive.</p><h3 id="noise-is-expected" tabindex="-1">Noise Is Expected <a class="header-anchor" href="#noise-is-expected" aria-label="Permalink to &quot;Noise Is Expected&quot;">​</a></h3><p>The AI surfaces everything that might represent an opportunity — feature ideas, problems, requests, and sentiment signals. It is deliberately non-judgmental. Not every Extract will be worth acting on, and that&#39;s fine. Noise is a natural byproduct of comprehensive signal capture, not a sign that something is wrong. The judgment about what matters belongs to you.</p><hr><h2 id="what-the-ai-analyzes-for" tabindex="-1">What the AI Analyzes For <a class="header-anchor" href="#what-the-ai-analyzes-for" aria-label="Permalink to &quot;What the AI Analyzes For&quot;">​</a></h2><p>When you upload a transcript, the AI scans it for:</p><ul><li><strong>Feature ideas</strong> — explicit or implied suggestions for new functionality</li><li><strong>Problems</strong> — pain points or frustrations mentioned by participants</li><li><strong>Requests</strong> — direct asks from customers or stakeholders</li><li><strong>Sentiment</strong> — emotional signals around existing features or experiences</li></ul><p>Each surfaced idea becomes an Extract with a generated Feature Name and Description, ready for your review.</p><hr><h2 id="how-extracts-relate-to-the-rest-of-lodestone" tabindex="-1">How Extracts Relate to the Rest of Lodestone <a class="header-anchor" href="#how-extracts-relate-to-the-rest-of-lodestone" aria-label="Permalink to &quot;How Extracts Relate to the Rest of Lodestone&quot;">​</a></h2><p>Extracts sit at the very beginning of the Lodestone planning stack. Their relationship to other objects is intentionally simple:</p><table tabindex="0"><thead><tr><th>Object</th><th>Relationship</th></tr></thead><tbody><tr><td>Features</td><td>An accepted Extract immediately becomes a Feature. All data carries over. From that point it behaves like any other Feature.</td></tr><tr><td>Documents, Roadmaps, Releases, Strategy</td><td>Extracts do not interact with these directly. Only accepted Extracts — now Features — participate downstream.</td></tr></tbody></table><p>This separation keeps discovery clean and distinct from planning.</p><hr><h2 id="source-badges" tabindex="-1">Source Badges <a class="header-anchor" href="#source-badges" aria-label="Permalink to &quot;Source Badges&quot;">​</a></h2><p>Each Extract displays a <strong>source badge</strong> indicating where it came from. This makes it easy to see at a glance whether an idea was surfaced from a customer call, a sales conversation, or a competitive analysis:</p><table tabindex="0"><thead><tr><th>Badge</th><th>Source</th></tr></thead><tbody><tr><td>Gong</td><td>Transcript imported from a Gong call</td></tr><tr><td>Fireflies</td><td>Transcript imported from a Fireflies meeting</td></tr><tr><td>Manual</td><td>Transcript uploaded directly by a team member</td></tr><tr><td>Intel Report</td><td>Extracted from a Competitive Intelligence report</td></tr></tbody></table><p>Source context is preserved when an Extract is promoted to a Feature — the source information carries over into the Feature&#39;s quote library.</p><hr><h2 id="supported-inputs" tabindex="-1">Supported Inputs <a class="header-anchor" href="#supported-inputs" aria-label="Permalink to &quot;Supported Inputs&quot;">​</a></h2><p>Extracts works with <strong>meeting transcripts in text format</strong> and <strong>Competitive Intelligence reports</strong>. Audio and video files are out of scope — these are handled upstream by recording platforms like Fireflies or Gong, which produce transcripts that are then brought into Lodestone.</p><p>Transcripts can be uploaded manually, imported directly via the Fireflies or Gong integrations, or fed from a completed Competitive Intelligence report via the Extract Features from Report action in the Intel module.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for uploading transcripts, reviewing Extracts, and promoting ideas to your backlog.</em></p>',43)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
